// Consolida todos los posts (primera página ya viene del HTTP Request)
// Si hay nextPageToken, se habrán manejado por paginación automática
// Este nodo estructura los datos para el procesamiento siguiente

const allItems = $input.all();
const config = $('Configuracion').first().json;

let allPosts = [];

for (const item of allItems) {
  const data = item.json;
  if (data.items && Array.isArray(data.items)) {
    allPosts = allPosts.concat(data.items);
  }
}

if (allPosts.length === 0) {
  return [{ json: { error: 'No se encontraron posts publicados', total: 0 } }];
}

// Estructurar cada post con sus labels
const posts = allPosts.map(post => ({
  id: post.id,
  title: post.title,
  url: post.url,
  labels: post.labels || [],
  content: post.content || '',
  published: post.published,
  BLOG_ID: config.BLOG_ID,
  LABEL_PILAR: config.LABEL_PILAR,
  SYSTEME_FUNNEL_URL: config.SYSTEME_FUNNEL_URL,
  MAX_INTERNAL_LINKS: config.MAX_INTERNAL_LINKS,
  allPostsSummary: allPosts.map(p => ({
    id: p.id,
    title: p.title,
    url: p.url,
    labels: p.labels || []
  }))
}));

return posts.map(p => ({ json: p }));

// Para este post, encuentra los posts relacionados por labels compartidas
// y construye el HTML de enlaces internos

const post = $input.item.json;
const allPosts = post.allPostsSummary;
const LABEL_PILAR = post.LABEL_PILAR;
const MAX_LINKS = post.MAX_INTERNAL_LINKS || 4;

// Posts del mismo cluster (comparten al menos una label, excluye el post actual)
const relatedPosts = allPosts
  .filter(p => {
    if (p.id === post.id) return false;
    if (!post.labels || post.labels.length === 0) return false;
    return p.labels.some(l => post.labels.includes(l));
  })
  .slice(0, MAX_LINKS);

// Identificar el pilar del cluster
const pillarPost = allPosts.find(p => 
  p.id !== post.id && 
  p.labels.includes(LABEL_PILAR) &&
  post.labels.some(l => p.labels.includes(l))
);

// Si no hay posts relacionados, saltar
if (relatedPosts.length === 0 && !pillarPost) {
  return { json: { ...post, skipUpdate: true, reason: 'Sin posts relacionados' } };
}

// Determinar si este post ES el pilar
const isThisPillar = post.labels.includes(LABEL_PILAR);

// Construir HTML de enlaces internos
let linksHTML = `\n<div class="cluster-links" style="background:#f8f9fa;border-left:4px solid #2563eb;padding:20px 24px;margin:32px 0;border-radius:0 8px 8px 0;font-family:inherit;">`;
linksHTML += `\n  <p style="font-weight:700;font-size:1.05em;margin:0 0 12px;color:#1e40af;">📚 Artículos relacionados en esta serie:</p>`;
linksHTML += `\n  <ul style="margin:0;padding-left:20px;">`;

for (const related of relatedPosts) {
  linksHTML += `\n    <li style="margin:6px 0;"><a href="${related.url}" title="${related.title}" style="color:#2563eb;text-decoration:none;">${related.title}</a></li>`;
}

linksHTML += `\n  </ul>`;

if (pillarPost && !isThisPillar) {
  linksHTML += `\n  <p style="margin:16px 0 0;">🏠 <strong><a href="${pillarPost.url}" title="${pillarPost.title}" style="color:#1e40af;">Ver guía completa: ${pillarPost.title}</a></strong></p>`;
}

linksHTML += `\n</div>`;

// Reemplazar el div existente o agregar al final
let newContent = post.content;
if (newContent.includes('<div class="cluster-links"')) {
  // Reemplazar el existente
  newContent = newContent.replace(/<div class="cluster-links"[\s\S]*?<\/div>/g, linksHTML);
} else {
  // Agregar al final
  newContent = newContent + linksHTML;
}

return {
  json: {
    ...post,
    newContent,
    skipUpdate: false,
    relatedCount: relatedPosts.length,
    hasPillar: !!pillarPost
  }
};

const items = $input.all();
const updatedCount = items.filter(i => i.json.id).length;

return [{
  json: {
    message: `✅ SEO Cluster Linker completado`,
    postsActualizados: updatedCount,
    timestamp: new Date().toISOString()
  }
}];
